CREATE TABLE "ImageMap" ("id" TEXT NOT NULL PRIMARY KEY, "ownerId" TEXT, "data" JSONB NOT NULL, "image" BLOB NOT NULL, "thumbnail" BLOB NOT NULL, "width" INTEGER NOT NULL, "height" INTEGER NOT NULL, "size" INTEGER NOT NULL, "version" INTEGER NOT NULL DEFAULT 1, "archived" BOOLEAN NOT NULL DEFAULT false, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL); CREATE INDEX "ImageMap_ownerId_archived_idx" ON "ImageMap"("ownerId", "archived");
